// Shared data contracts for the Filed Under dataset. Files under public/data/
// are generated by scripts/ingest.ts from SEC EDGAR, Yahoo Finance and FRED.

export type Unit = "usd" | "usdPerShare" | "shares" | "pct" | "ratio" | "days";

export interface SourceRef {
  /** SEC accession number, e.g. 0000320193-25-000079 */
  accn: string;
  /** Fully-qualified XBRL concept, e.g. us-gaap:NetIncomeLoss */
  concept: string;
  start?: string;
  end: string;
  value: number;
  /** Document inside the filing (e.g. an EX-99 press release) when it isn't the primary document */
  doc?: string;
  /** Table cell locator for non-XBRL documents: table / row / cell index in document order */
  cell?: { t: number; r: number; c: number };
  /** Region on a page image (slides read by vision): page number and [x0, y0, x1, y1] as fractions */
  box?: { p: number; b: number[] };
  /** Stored investor-relations document id (press release, supplement, presentation) when not an EDGAR document */
  irDoc?: string;
}

export interface DerivedPart extends SourceRef {
  label: string;
  sign: 1 | -1;
}

export interface Cell {
  v: number;
  src?: SourceRef;
  /** Other filings that reported the identical value for the same period */
  alts?: string[];
  derived?: { formula: string; parts: DerivedPart[] };
  approx?: boolean;
}

export interface Period {
  key: string;
  label: string;
  fy: number;
  fq?: number;
  start?: string;
  end: string;
}

export interface Row {
  key: string;
  label: string;
  unit: Unit;
  cells: (Cell | null)[];
  indent?: number;
  bold?: boolean;
  kind?: "reported" | "kpi";
}

export interface Statement {
  periods: Period[];
  rows: Row[];
}

export type StatementKey = "income" | "balance" | "cashflow" | "kpis";

export interface Filing {
  accn: string;
  form: string;
  filed: string;
  report?: string;
  doc: string;
  desc?: string;
  items?: string;
  ixbrl?: boolean;
  size?: number;
}

export type SegmentMetric = "revenue" | "operatingIncome" | "grossProfit" | "netIncome" | "assets" | "capex" | "dna";

export interface SegmentFact {
  axis: string;
  axisLabel: string;
  member: string;
  label: string;
  metric: SegmentMetric;
  concept: string;
  start?: string;
  end: string;
  value: number;
  accn: string;
  elementId?: string;
}

export interface InsiderTrade {
  accn: string;
  filed: string;
  owner: string;
  role: string;
  date: string;
  code: string;
  security: string;
  shares: number;
  price: number | null;
  acquired: boolean;
  ownedAfter: number | null;
  direct: boolean;
  plan10b5: boolean;
  doc: string;
}

export interface EarningsRelease {
  accn: string;
  filed: string;
  report?: string;
  doc: string;
  title: string;
}

export interface CompanyProfile {
  ticker: string;
  cik: string;
  name: string;
  exchange: string;
  sic: string;
  sicDescription: string;
  sector: string;
  industry: string;
  fiscalYearEnd: string;
  stateOfIncorporation: string;
  ein: string;
  phone: string;
  address: { street: string; city: string; state: string; zip: string };
  website: string;
  investorRelations: string;
  description: string;
  logo: string;
  founded: number;
  ceo: string;
  sharesOutstanding: number | null;
  sharesOutstandingAsOf: string | null;
  sharesOutstandingAccn: string | null;
  filerCategory: string;
  formerNames: { name: string; from: string; to: string }[];
}

export interface CompanyDataset {
  generatedAt: string;
  profile: CompanyProfile;
  filings: Filing[];
  statements: {
    annual: Record<StatementKey, Statement>;
    quarterly: Record<StatementKey, Statement>;
  };
  segments: SegmentFact[];
  insiders: InsiderTrade[];
  earningsReleases: EarningsRelease[];
}

export interface UniverseEntry {
  ticker: string;
  name: string;
  cik: string;
  sector: string;
  industry: string;
  exchange: string;
  logo: string;
  city: string;
  state: string;
  fiscalYearEnd: string;
  latestFY: string;
  revenueFY: number | null;
  netIncomeFY: number | null;
  revenueTTM: number | null;
  netIncomeTTM: number | null;
  fcfTTM: number | null;
  epsTTM: number | null;
  grossMarginTTM: number | null;
  revenueGrowthYoY: number | null;
  sharesOutstanding: number | null;
  lastFiling: { form: string; filed: string; accn: string } | null;
  /** Compact fundamentals for screens and sector roll-ups (all from the SEC statements). */
  f?: UniverseFundamentals;
}

export type TtmKey =
  | "revenue"
  | "grossProfit"
  | "operatingIncome"
  | "ebitda"
  | "netIncome"
  | "fcf"
  | "cfo"
  | "capex"
  | "sbc"
  | "rnd"
  | "dna"
  | "buybacks"
  | "dividends"
  | "epsDiluted"
  | "interestExpense";

export type BalanceKey = "cash" | "shortTermInvestments" | "totalDebt" | "netDebt" | "equity" | "totalAssets" | "loans" | "deposits";

export interface UniverseFundamentals {
  /** End date of the latest quarter in the TTM window */
  asOf: string | null;
  ttm: Partial<Record<TtmKey, number>>;
  bs: Partial<Record<BalanceKey, number>>;
  /** Last ten fiscal years of revenue */
  revenueHistory: [string, number][];
  revenueCagr3y: number | null;
  revenueCagr5y: number | null;
  epsGrowthYoY: number | null;
  /** Latest quarter's weighted diluted shares */
  dilutedShares: number | null;
}

export interface Universe {
  generatedAt: string;
  companies: UniverseEntry[];
}

/** Compact OHLCV bars: [isoDate, open, high, low, close, adjClose, volume] */
export type Bar = [string, number, number, number, number, number, number];

export interface PriceSeries {
  symbol: string;
  name?: string;
  currency: string;
  interval: string;
  bars: Bar[];
  fetchedAt: string;
  source: "yahoo-live" | "snapshot";
}

export interface MacroSeries {
  id: string;
  title: string;
  units: string;
  frequency: string;
  observations: [string, number][];
  fetchedAt: string;
  source: "fred-live" | "treasury-live" | "cloud" | "snapshot";
  agency?: string;
}
